#!/usr/bin/env bash
# Builds the Android library (AAR) of the native SDK:
#   * libzenollull.so for arm64-v8a, armeabi-v7a and x86_64 (cargo-ndk),
#   * the Kotlin bindings generated by UniFFI,
#   * packaged by Gradle into sdk/android/zenollull/build/outputs/aar.
#
# Requires: Android NDK (ANDROID_NDK_HOME), cargo-ndk, Gradle, JDK 17, and
#   rustup target add aarch64-linux-android armv7-linux-androideabi x86_64-linux-android
set -euo pipefail
cd "$(dirname "$0")/.."

MODULE=sdk/android/zenollull
rm -rf "$MODULE/src/main/jniLibs" "$MODULE/src/main/java"

cargo ndk -t arm64-v8a -t armeabi-v7a -t x86_64 \
  -o "$MODULE/src/main/jniLibs" build --release -p mobile-ffi

# The bindings are generated from a host build of the same crate.
cargo build --release -p mobile-ffi
HOST_LIB=target/release/libzenollull.so
[ -f "$HOST_LIB" ] || HOST_LIB=target/release/libzenollull.dylib
./target/release/uniffi-bindgen generate --library "$HOST_LIB" \
  --language kotlin --out-dir "$MODULE/src/main/java"

(cd sdk/android && gradle --no-daemon :zenollull:assembleRelease)
ls -l "$MODULE"/build/outputs/aar/
